source='''def transform(grid):
    h = len(grid)
    w = 7
    out = [[0] * w for _ in range(h)]
    marker = next(( (r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5), None)
    if marker is None:
        return out
    r, c = marker
    x = c - 8
    out[r][x] = 5
    tiles = []
    for col0 in (0, 4):
        for r0 in range(0, h, 4):
            cells = [(rr, cc) for rr in range(r0, min(r0 + 3, h))
                     for cc in range(col0, min(col0 + 3, len(grid[rr])))
                     if grid[rr][cc] != 0]
            if not cells:
                continue
            color = grid[cells[0][0]][cells[0][1]]
            # The tile symbols encode the path direction and stroke length.
            if color == 1:
                direction, length = 'right', 3
            elif color == 2:
                direction, length = 'left', 2
            elif color == 3:
                direction, length = 'left', 4
            elif color == 6:
                direction, length = 'down', 2
            else:
                continue
            tiles.append((color, direction, length))
    for color, direction, length in tiles:
        r += 1
        if direction == 'right':
            for k in range(length):
                if 0 <= r < h and 0 <= x + k < w:
                    out[r][x + k] = color
            x += length - 1
        elif direction == 'left':
            for k in range(length):
                if 0 <= r < h and 0 <= x - k < w:
                    out[r][x - k] = color
            x -= length - 1
        else:
            for k in range(length):
                if 0 <= r + k < h and 0 <= x < w:
                    out[r + k][x] = color
            r += length - 1
    return out
'''
